
import fs from 'fs';
import { v4 as uuidv4 } from 'uuid';

const invalidUsers = JSON.parse(fs.readFileSync('invalid_users.json', 'utf8'));

let migrationSQL = `-- Users Table UUID Migration V5 (Universal FK + Policy Safe)
-- Generated by Antigravity Agent
-- Date: ${new Date().toISOString()}

BEGIN;

-- 1. Drop ALL Blocking Policies (Known)
DROP POLICY IF EXISTS "Enable update for creators and admins" ON public.school_outreach_reports;
DROP POLICY IF EXISTS "Enable read access for all authenticated users" ON public.school_outreach_reports;
DROP POLICY IF EXISTS "Enable insert for authenticated users" ON public.school_outreach_reports;
DROP POLICY IF EXISTS "Admins manage reports" ON public.monitoring_reports;
DROP POLICY IF EXISTS "View published reports" ON public.monitoring_reports;
DROP POLICY IF EXISTS "HoDs manage their submissions" ON public.report_submissions;

-- 2. Drop Blocking Foreign Keys (With Checks)
DO $$ BEGIN
    -- Known FKs
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'volunteer_attendance_volunteer_id_fkey') THEN
        ALTER TABLE public.volunteer_attendance DROP CONSTRAINT volunteer_attendance_volunteer_id_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'training_requests_requester_id_fkey') THEN
        ALTER TABLE public.training_requests DROP CONSTRAINT training_requests_requester_id_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'school_outreach_reports_submitted_by_fkey') THEN
        ALTER TABLE public.school_outreach_reports DROP CONSTRAINT school_outreach_reports_submitted_by_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'monitoring_reports_created_by_fkey') THEN
        ALTER TABLE public.monitoring_reports DROP CONSTRAINT monitoring_reports_created_by_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'report_submissions_submitted_by_fkey') THEN
        ALTER TABLE public.report_submissions DROP CONSTRAINT report_submissions_submitted_by_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'departments_head_id_fkey') THEN
        ALTER TABLE public.departments DROP CONSTRAINT departments_head_id_fkey;
    END IF;
    -- Suspected/Likely FKs (Checking existence of table first implies safety somewhat, but constraint check is better)
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'department_requests_user_id_fkey') THEN
        ALTER TABLE public.department_requests DROP CONSTRAINT department_requests_user_id_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'vehicle_checkouts_coordinator_id_fkey') THEN
        ALTER TABLE public.vehicle_checkouts DROP CONSTRAINT vehicle_checkouts_coordinator_id_fkey;
    END IF;
     IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'vehicles_coordinator_uid_fkey') THEN
        ALTER TABLE public.vehicles DROP CONSTRAINT vehicles_coordinator_uid_fkey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints WHERE constraint_name = 'incidents_reported_by_fkey') THEN
        ALTER TABLE public.incidents DROP CONSTRAINT incidents_reported_by_fkey;
    END IF;
END $$;


-- 3. Data Correction (Users Table)
`;

let rollbackSQL = `-- Users Table UUID Rollback V5
-- Generated by Antigravity Agent

BEGIN;

-- 1. Revert Type (Users)
ALTER TABLE users ALTER COLUMN id TYPE text;
ALTER TABLE users ALTER COLUMN id DROP DEFAULT;

-- 2. Revert Type (Dependents - Universal Check)
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'volunteer_attendance' AND column_name = 'volunteer_id') THEN
        ALTER TABLE volunteer_attendance ALTER COLUMN volunteer_id TYPE text;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'training_requests' AND column_name = 'requester_id') THEN
        ALTER TABLE training_requests ALTER COLUMN requester_id TYPE text;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'school_outreach_reports' AND column_name = 'submitted_by') THEN
        ALTER TABLE school_outreach_reports ALTER COLUMN submitted_by TYPE text;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'monitoring_reports' AND column_name = 'created_by') THEN
        ALTER TABLE monitoring_reports ALTER COLUMN created_by TYPE text;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'report_submissions' AND column_name = 'submitted_by') THEN
        ALTER TABLE report_submissions ALTER COLUMN submitted_by TYPE text;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'departments' AND column_name = 'head_id') THEN
        ALTER TABLE departments ALTER COLUMN head_id TYPE text;
    END IF;
    -- Suspected
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'department_requests' AND column_name = 'user_id') THEN
        ALTER TABLE department_requests ALTER COLUMN user_id TYPE text;
    END IF;
     IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'vehicles' AND column_name = 'coordinator_uid') THEN
        ALTER TABLE vehicles ALTER COLUMN coordinator_uid TYPE text;
    END IF;
     IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'incidents' AND column_name = 'reported_by') THEN
        ALTER TABLE incidents ALTER COLUMN reported_by TYPE text;
    END IF;
END $$;


-- 3. Restore Legacy IDs (Users)
`;

// Reuse ID mapping
invalidUsers.forEach(u => {
    const newUUID = uuidv4();
    migrationSQL += `UPDATE users SET id = '${newUUID}' WHERE id = '${u.id}'; -- Was: ${u.username}\n`;
    rollbackSQL += `UPDATE users SET id = '${u.id}' WHERE id = '${newUUID}'; -- Restore ${u.username}\n`;
});

migrationSQL += `
-- 4. Schema Hardening (Users)
ALTER TABLE users ALTER COLUMN id SET DEFAULT gen_random_uuid();

-- 5. Type Conversion (Users)
ALTER TABLE users ALTER COLUMN id TYPE uuid USING id::uuid;

-- 6. Type Conversion (Dependents) WITH CHECKS
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'volunteer_attendance' AND column_name = 'volunteer_id') THEN
        ALTER TABLE public.volunteer_attendance ALTER COLUMN volunteer_id TYPE uuid USING volunteer_id::uuid;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'training_requests' AND column_name = 'requester_id') THEN
        ALTER TABLE public.training_requests ALTER COLUMN requester_id TYPE uuid USING requester_id::uuid;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'school_outreach_reports' AND column_name = 'submitted_by') THEN
        ALTER TABLE public.school_outreach_reports ALTER COLUMN submitted_by TYPE uuid USING submitted_by::uuid;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'monitoring_reports' AND column_name = 'created_by') THEN
        ALTER TABLE public.monitoring_reports ALTER COLUMN created_by TYPE uuid USING created_by::uuid;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'report_submissions' AND column_name = 'submitted_by') THEN
        ALTER TABLE public.report_submissions ALTER COLUMN submitted_by TYPE uuid USING submitted_by::uuid;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'departments' AND column_name = 'head_id') THEN
        ALTER TABLE public.departments ALTER COLUMN head_id TYPE uuid USING head_id::uuid;
    END IF;
    -- Suspected
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'department_requests' AND column_name = 'user_id') THEN
        ALTER TABLE public.department_requests ALTER COLUMN user_id TYPE uuid USING user_id::uuid;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'vehicles' AND column_name = 'coordinator_uid') THEN
        ALTER TABLE public.vehicles ALTER COLUMN coordinator_uid TYPE uuid USING coordinator_uid::uuid;
    END IF;
     IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'incidents' AND column_name = 'reported_by') THEN
        ALTER TABLE public.incidents ALTER COLUMN reported_by TYPE uuid USING reported_by::uuid;
    END IF;
END $$;

-- 7. Restore Foreign Keys (With Checks)
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'volunteer_attendance' AND column_name = 'volunteer_id') THEN
        ALTER TABLE public.volunteer_attendance ADD CONSTRAINT volunteer_attendance_volunteer_id_fkey FOREIGN KEY (volunteer_id) REFERENCES public.users(id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'training_requests' AND column_name = 'requester_id') THEN
        ALTER TABLE public.training_requests ADD CONSTRAINT training_requests_requester_id_fkey FOREIGN KEY (requester_id) REFERENCES public.users(id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'school_outreach_reports' AND column_name = 'submitted_by') THEN
        ALTER TABLE public.school_outreach_reports ADD CONSTRAINT school_outreach_reports_submitted_by_fkey FOREIGN KEY (submitted_by) REFERENCES public.users(id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'monitoring_reports' AND column_name = 'created_by') THEN
        ALTER TABLE public.monitoring_reports ADD CONSTRAINT monitoring_reports_created_by_fkey FOREIGN KEY (created_by) REFERENCES public.users(id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'report_submissions' AND column_name = 'submitted_by') THEN
        ALTER TABLE public.report_submissions ADD CONSTRAINT report_submissions_submitted_by_fkey FOREIGN KEY (submitted_by) REFERENCES public.users(id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'departments' AND column_name = 'head_id') THEN
        ALTER TABLE public.departments ADD CONSTRAINT departments_head_id_fkey FOREIGN KEY (head_id) REFERENCES public.users(id);
    END IF;
    -- Suspected
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'department_requests' AND column_name = 'user_id') THEN
        ALTER TABLE public.department_requests ADD CONSTRAINT department_requests_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'vehicles' AND column_name = 'coordinator_uid') THEN
        ALTER TABLE public.vehicles ADD CONSTRAINT vehicles_coordinator_uid_fkey FOREIGN KEY (coordinator_uid) REFERENCES public.users(id);
    END IF;
     IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'incidents' AND column_name = 'reported_by') THEN
        ALTER TABLE public.incidents ADD CONSTRAINT incidents_reported_by_fkey FOREIGN KEY (reported_by) REFERENCES public.users(id);
    END IF;
END $$;


-- 8. Restore Policies (UUID-Aware)
-- (Same as V4)

-- school_outreach_reports
CREATE POLICY "Enable update for creators and admins" ON public.school_outreach_reports
    FOR UPDATE USING (
        (auth.uid() = submitted_by) OR 
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() 
            AND (users.role IN ('Super Admin', 'Administrator', 'Head of Dept'))
        )
    );

CREATE POLICY "Enable read access for all authenticated users" ON public.school_outreach_reports
    FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Enable insert for authenticated users" ON public.school_outreach_reports
    FOR INSERT WITH CHECK (auth.role() = 'authenticated');

-- monitoring_reports
CREATE POLICY "Admins manage reports" ON public.monitoring_reports
    USING (
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() 
            AND users.role IN ('Super Admin', 'Administrator')
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() 
            AND users.role IN ('Super Admin', 'Administrator')
        )
    );

CREATE POLICY "View published reports" ON public.monitoring_reports
    FOR SELECT USING (status = 'Published' OR status = 'Expired');

-- report_submissions
CREATE POLICY "HoDs manage their submissions" ON public.report_submissions
    USING (
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() 
            AND users.department_id = report_submissions.department_id
        )
        OR
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() 
            AND users.role IN ('Super Admin', 'Administrator', 'Team Leader')
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id = auth.uid() 
            AND users.department_id = report_submissions.department_id
        )
    );

COMMIT;
`;

rollbackSQL += `
COMMIT;
`;

fs.writeFileSync('d:/Manifest System/backend/database/users_uuid_migration_v5.sql', migrationSQL);
fs.writeFileSync('d:/Manifest System/backend/database/users_uuid_rollback_v5.sql', rollbackSQL);

console.log("Generated V5 migration and rollback scripts.");
